from collections import deque

class Solution:
    def deckRevealedIncreasing(self, deck: List[int]) -> List[int]:
        n = len(deck)
        q = deque(range(n))
        reveal_order = []
        while q:
            reveal_order.append(q.popleft())
            if q:
                q.append(q.popleft())
        deck.sort()
        result = [0] * n
        for card, pos in zip(deck, reveal_order):
            result[pos] = card
        return result

