from collections import Counter
from typing import List

class Solution:
    def countCharacters(self, words: List[str], chars: str) -> int:
        base_counter = Counter(chars)
        total = 0
        for word in words:
            word_counter = Counter(word)
            # ensure each char count in word fits within chars
            if all(word_counter[ch] <= base_counter.get(ch, 0) for ch in word_counter):
                total += len(word)
        return total

