class Solution:
    def numOfPairs(self, nums: List[str], target: str) -> int:
        from collections import Counter
        cnt = Counter(nums)
        ans = 0
        n = len(target)
        for i in range(1, n):
            left = target[:i]
            right = target[i:]
            c_left = cnt[left]
            c_right = cnt[right]
            if c_left and c_right:
                if left == right:
                    ans += c_left * (c_left - 1) // 2
                else:
                    ans += c_left * c_right
        return ans

