from functools import lru_cache

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        n, m = len(word1), len(word2)

        @lru_cache(None)
        def rec(i: int, j: int) -> int:
            if i == n and j == m:
                return 0
            elif i == n:
                return m - j
            elif j == m:
                return n - i
            elif word1[i] == word2[j]:
                return rec(i + 1, j + 1)
            else:
                insert = 1 + rec(i, j + 1)      # insert a char from word2
                delete = 1 + rec(i + 1, j)      # delete a char from word1
                replace = 1 + rec(i + 1, j + 1) # replace char
                return min(insert, delete, replace)

        return rec(0, 0)
